def is_priem(n):
    if n < 2:
        return False
    deler = 2
    while deler * deler <= n:
        if n % deler == 0:
            return False
        deler += 1
    return True


def toon_priemgetallen(tot):
    print(*[n for n in range(tot) if is_priem(n)])


def aantal_priemgetallen(tot):
    return sum(1 for n in range(tot) if is_priem(n))
